@page "/chat"
@using sv_1ed208477873442b944a21606a54f0b7.Components.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelList Channels="_channels"
                 SelectedChannelId="_selectedChannelId"
                 OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_threadOpen ? "thread-open" : "")">
        <MessageArea ChannelName="@(_selectedChannel?.Name ?? "")"
                     ChannelDescription="@(_selectedChannel?.Description ?? "")"
                     Messages="_messages"
                     ThreadReplyCounts="_threadReplyCounts"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     ThreadMessages="_threadMessages"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel>? _channels;
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = new();
    private Dictionary<int, int> _threadReplyCounts = new();

    private bool _threadOpen;
    private int _threadRootMessageId;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;

    private int _pageSize = 30;
    private bool _allMessagesLoaded;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _messages = new();
        _threadReplyCounts = new();
        _allMessagesLoaded = false;

        CloseThreadSync();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, _pageSize);
        _messages = messages;

        await LoadThreadCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count in local state
        if (_channels is not null)
        {
            var idx = _channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                var ch = _channels[idx];
                _channels[idx] = ch with { UnreadCount = 0 };
            }
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_allMessagesLoaded) return;

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, _pageSize);
        if (older.Count < _pageSize)
        {
            _allMessagesLoaded = true;
        }

        _messages.InsertRange(0, older);
        await LoadThreadCounts();
    }

    private async Task LoadThreadCounts()
    {
        // Identify messages that have replies (where another message's ReplyToId points to them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            if (!_threadReplyCounts.ContainsKey(rootId))
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    _threadReplyCounts[rootId] = thread.Count;
                }
            }
        }
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessageId = messageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        _threadMessages = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;

        _threadReplyCounts[messageId] = _threadMessages.Count;
    }

    private void CloseThread()
    {
        CloseThreadSync();
    }

    private void CloseThreadSync()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessageId);
        _threadMessages?.Add(reply);

        _threadReplyCounts[_threadRootMessageId] = _threadMessages?.Count ?? 0;
    }

    private async Task HandleReaction((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);

        // Optimistically update local state
        var msg = _messages.FirstOrDefault(m => m.Id == reaction.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(reaction.Emoji, new List<string> { "You" }));
            }
        }
    }
}

