toolArgs.file_text:
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    min-width: 0;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #f2f3f5;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #949ba4;
    font-size: 0.85rem;
}

.message-input-area {
    padding: 12px 16px;
    border-top: 1px solid #1e1f22;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-input-area textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    color: #f2f3f5;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
    outline: none;
}

.message-input-area textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.send-btn {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 6px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

