+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 4px;
+}
+
+.thread-message-item .message-author {
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #f2f3f5;
+}
+
+.thread-message-item .message-time {
+    font-size: 0.7rem;
+    color: #949ba4;
+}
+
+.thread-message-item .message-content {
+    font-size: 0.85rem;
+    color: #dbdee1;
+    line-height: 1.3;
+}
+
+.thread-input-area {
+    padding: 12px 16px;
+    border-top: 1px solid #1e1f22;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.thread-input-area textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    color: #f2f3f5;
+    padding: 8px 12px;
+    font-size: 0.85rem;
+    resize: none;
+    font-family: inherit;
+    outline: none;
+}
+
+.thread-input-area textarea:focus {
+    box-shadow: 0 0 0 2px #5865f2;
+}
+
+.thread-input-area .send-btn {
+    background: #5865f2;
+    color: white;
+    border: none;
+    border-radius: 6px;
+    padding: 8px 16px;
+    font-weight: 600;
+    font-size: 0.8rem;
+    cursor: pointer;
+}
+
+.thread-input-area .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.thread-input-area .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+

